  layers(g, [50, 3, 10], legend, [
    // y3: barrel, table legs, smoker, benches
    ["b       ", "b f  f  ", " Mf  f  ", "  N  N  ", "        ", "        "],
    // y4: table top (top slabs over x52..55 z11..12)
    ["        ", "  TTTT  ", "  TTTT  ", "        ", "        ", "        "],
    // y5: cauldron on the table
    ["        ", "    C   ", "        ", "        ", "        ", "        "],
    // y6: hanging lanterns under the ceiling
    ["        ", "        ", "   L    ", "        ", "L     L ", "        "],
  ]);
}

