mkdir -p /tmp/room20-test && cat > /tmp/room20-test/shellify.mjs <<'EOF'
// Scratch: adds a temporary floor, walls, ceiling and open front door around the room, to test the walk only.
import { load, Grid } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
const [inPath, outPath] = process.argv.slice(2);
const g = load(inPath);
const W = "stone_bricks";
for (let x = 49; x <= 58; x++) for (let z = 9; z <= 16; z++) g.set(x, 2, z, "spruce_planks");
for (let x = 49; x <= 58; x++) for (let z = 9; z <= 16; z++) g.set(x, 7, z, "spruce_planks");
for (let y = 3; y <= 6; y++) {
  for (let x = 49; x <= 58; x++) { g.set(x, y, 9, W); g.set(x, y, 16, W); }
  for (let z = 9; z <= 16; z++) { g.set(49, y, z, W); g.set(58, y, z, W); }
}
for (let y = 3; y <= 4; y++) { g.set(53, y, 9, "air"); g.set(54, y, 9, "air"); }
g.set(56, 3, 16, "air"); g.set(56, 4, 16, "air");
g.save(outPath);
console.log("wrote", outPath, g.refused.length, "refused");
EOF
node /tmp/room20-test/shellify.mjs build.nbt /tmp/room20-test/test.nbt && MCD="/Volumes/ext1/swe/repos/minecraft-design/tools/bin/mcd.mjs" && node $MCD room /tmp/room20-test/test.nbt --rooms rooms.json --only "Boarding house kitchen-hall" 2>&1 | head -40; date

